// 文脈選詞 B：和語動詞（含複合動詞）、形容詞、副詞、擬聲擬態語。正解寫在第一個選項。
Bank.group('context-b', '文脈選詞', [
  // 和語動詞・複合動詞
  ['寝坊して、いつもの電車に（　）しまった。', '乗り遅れて', '乗り越して', '乗り換えて', '乗り込んで', '「電車に乗り遅れる」是沒趕上車。「乗り越す」是坐過站，必須已經在車上，與「寝坊」不合。'],
  ['母に頼まれた牛乳を（　）、もう一度スーパーに行った。', '買い忘れて', '買い占めて', '買い替えて', '買い込んで', '「買い忘れる」是忘了買，所以才要再跑一趟。「買い込む」是大量買進，不需要再回去。'],
  ['旅行に行くために、毎月少しずつお金を（　）いる。', '貯めて', '積んで', '重ねて', '詰めて', '存錢用「お金を貯める」。「積む」是堆疊，「お金を積む」指拿出大筆錢，不是每月儲蓄。'],
  ['お客さんが来る前に、散らかった部屋を（　）。', '片付けた', '落ち着けた', '取り消した', '包んだ', '「部屋を片付ける」是整理房間。「落ち着ける」是使心情平靜，不能用在房間。'],
  ['友達に飲み会に誘われたが、熱があったので（　）。', '断った', '認めた', '招いた', '許した', '拒絕邀約用「断る」。「認める」是承認、認可，與「誘われたが」的轉折不搭。'],
  ['駅まで走ったおかげで、最終電車に何とか（　）。', '間に合った', '追いついた', '向かった', '届いた', '「電車に間に合う」是趕上班次。「追いつく」是追上移動中的對象，不用於趕上發車時間。'],
  ['大学に進むか就職するか、まだ（　）いる。', '悩んで', '慌てて', '諦めて', '怒って', '「〜か〜か悩んでいる」表示猶豫不決。「諦める」是放棄，不能接「まだ〜ている」表達還在選擇。'],
  ['雨が強くなったので、山に登るのを（　）。', '諦めた', '譲った', '防いだ', '逃した', '「〜のを諦める」是放棄做某事。「逃す」是錯失機會，主語自己決定不爬山不能用「逃した」。'],
  ['電車でお年寄りに席を（　）。', '譲った', '貸した', '預けた', '渡した', '讓座固定說「席を譲る」。「貸す」是借出，之後要歸還，不用於讓座。'],
  ['店員にプレゼントをきれいな紙で（　）もらった。', '包んで', '塗って', '縛って', '畳んで', '用紙包裝禮物是「紙で包む」。「縛る」是用繩子綁，不用「紙で」。'],
  ['乾いた洗濯物を（　）、たんすにしまった。', '畳んで', '干して', '絞って', '濡らして', '把衣服摺好收進衣櫃用「畳む」。「干す」是晾乾，衣服已經「乾いた」，不需要再晾。'],
  ['天気がいいので、布団をベランダに（　）。', '干した', '敷いた', '畳んだ', '揃えた', '天氣好時把棉被拿到陽台曬是「布団を干す」。「敷く」是把棉被鋪在床上或地上睡覺用。'],
  ['話に夢中になっていたら、コーヒーがすっかり（　）しまった。', '冷めて', '溶けて', '乾いて', '枯れて', '熱的食物飲料變涼用「冷める」。「溶ける」是固體融化，不用於熱飲。'],
  ['旅行中、水をやる人がいなかったので、庭の花が（　）しまった。', '枯れて', '崩れて', '破れて', '溶けて', '植物缺水凋萎是「枯れる」。「崩れる」是建築、山坡等崩塌。'],
  ['写真を撮るので、眼鏡を（　）ください。', '外して', '脱いで', '抜いて', '離して', '取下眼鏡、手錶、飾品用「外す」。「脱ぐ」用於衣服、鞋子等穿在身上的東西。'],
  ['その帽子、あなたにとてもよく（　）ね。', '似合います', '合わせます', '似ています', '向きます', '「〜に似合う」是穿戴起來很適合。「似ている」是外表相像，帽子不會和人相像。'],
  ['面接の前は緊張していたが、深呼吸をしたら少し（　）。', '落ち着いた', '落ち込んだ', '片付いた', '止まった', '緊張後恢復平靜是「落ち着く」。「落ち込む」是心情低落，與深呼吸後變好的語意相反。'],
  ['試合に負けて（　）いる弟を、家族みんなで励ました。', '落ち込んで', '落ち着いて', '盛り上がって', '張り切って', '輸了比賽而沮喪是「落ち込む」，所以家人要鼓勵他。「張り切る」是幹勁十足，不需要人鼓勵。'],
  ['初めての発表会なので、娘は朝から（　）いる。', '張り切って', '落ち込んで', '呆れて', '諦めて', '「張り切る」表示充滿幹勁、躍躍欲試。第一次上台發表通常令人期待，「落ち込む」與情境不合。'],
  ['忙しかったが、先輩に頼まれた仕事を（　）。', '引き受けた', '引き返した', '打ち明けた', '取り出した', '接下別人拜託的工作是「仕事を引き受ける」。「引き返す」是折返原路。'],
  ['誰にも言えなかった悩みを、親友にだけ（　）。', '打ち明けた', '話し合った', '言い返した', '呼びかけた', '把藏在心裡的事坦白說出來是「打ち明ける」。「話し合う」要說「〜と話し合う」，助詞不合。'],
  ['散歩をしているときに、いいアイデアを（　）。', '思いついた', '思い込んだ', '見送った', '言いつけた', '突然想到點子是「アイデアを思いつく」。「思い込む」是一廂情願地認定，不接「アイデアを」。'],
  ['留学する友人を、空港で（　）。', '見送った', '見逃した', '見下ろした', '見上げた', '到機場為人送行是「見送る」。「見逃す」是錯過沒看到或放過，與送行無關。'],
  ['残業で帰りが遅くなり、毎週見ているドラマを（　）しまった。', '見逃して', '見送って', '見落として', '見下ろして', '錯過想看的節目是「見逃す」。「見落とす」是看漏細節，例如文件中的錯字，不用於節目。'],
  ['急な用事ができたので、ホテルの予約を（　）。', '取り消した', '取り出した', '取り替えた', '取り上げた', '取消預約是「予約を取り消す」。「取り替える」是更換成別的東西。'],
  ['週に二回、駅前のスポーツクラブに（　）いる。', '通って', '渡って', '過ごして', '移って', '定期往返某處是「〜に通う」。「渡る」是橫越道路、橋梁等。'],
  ['夜の間に、雪が三十センチも（　）。', '積もった', '重なった', '増やした', '詰まった', '雪、灰塵堆積用「積もる」。「重なる」是物品一層層疊在一起，不用於積雪。'],
  ['台所の排水口が髪の毛やごみで（　）、水が流れなくなった。', '詰まって', '積もって', '閉まって', '縛って', '管子被東西塞住是「詰まる」。「閉まる」是門窗關上，不用於排水口堵塞。'],
  ['遊びに行く前に、宿題を（　）おきなさい。', '済ませて', '終わって', '片付いて', '間に合って', '「宿題を済ませる」是把作業做完。「終わる」是自動詞，要說「終わらせて」才能接「宿題を」。'],
  ['約束の時間に遅れたことを、友達に（　）。', '謝った', '許した', '責めた', '誘った', '為自己遲到向朋友道歉是「〜に謝る」。「責める」要說「友達を責める」，而且遲到的是自己。'],

  // 形容詞
  ['窓から入る朝日が（　）て、目を開けていられなかった。', 'まぶしく', '激しく', '鋭く', '濃く', '光線強到刺眼是「まぶしい」。「激しい」形容雨勢、動作等劇烈，不用於陽光刺眼。'],
  ['小学校のころの写真を見て、（　）気持ちになった。', '懐かしい', '悔しい', '怪しい', '羨ましい', '看到過去的照片而想念以前是「懐かしい」。「悔しい」是不甘心，與看舊照片無關。'],
  ['一点差で決勝戦に負けて、とても（　）。', '悔しかった', '懐かしかった', '珍しかった', '怪しかった', '差一點就贏卻輸了的不甘心是「悔しい」。「懐かしい」是懷念過去。'],
  ['風邪をひいたのか、体が（　）て、何もしたくない。', 'だるく', '鈍く', '硬く', '浅く', '生病時全身無力、提不起勁是「だるい」。「鈍い」是遲鈍，「体が硬い」是身體柔軟度差。'],
  ['まだ十分使えるのに捨てるなんて、（　）。', 'もったいない', '情けない', '申し訳ない', 'だらしない', '東西還能用卻丟掉，覺得浪費可惜是「もったいない」。「だらしない」是邋遢、散漫。'],
  ['何度断っても、その店員は（　）商品を勧めてきた。', 'しつこく', '厳しく', '激しく', '細かく', '拒絕好幾次仍一直糾纏是「しつこい」。「厳しい」是嚴格，不是糾纏不休。'],
  ['兄は（　）なので、百円も貸してくれない。', 'けち', '素直', '派手', '丁寧', '連一百日圓都不肯借，表示小氣「けち」。「派手」是花俏，與不肯借錢無關。'],
  ['雨で外に出られず、家ですることもなくて、一日中（　）だった。', '退屈', '不安', '迷惑', '平気', '「することもなくて」表示無事可做，覺得無聊是「退屈」。「不安」是擔心，句中沒有令人擔憂的事；「平気」是不在乎、沒關係，和無事可做的心情不合。'],
  ['皿を割ったことを母に（　）に話したら、許してくれた。', '正直', '確か', '盛ん', '意外', '老實說出自己做錯的事是「正直に話す」。「確か」是確實，不用來形容坦白認錯。'],
  ['お葬式には、（　）な服を着ていかないほうがいい。', '派手', '丈夫', '清潔', '器用', '喪禮應避免穿著鮮豔花俏的「派手な服」。「丈夫」是耐用，與場合禮節無關。'],
  ['留学中の経験は、私にとって（　）な思い出になった。', '貴重', '重大', '高価', '豊富', '難得而珍貴的經驗、回憶用「貴重」。「高価」是價格高，不能修飾回憶。'],
  ['夜遅くに大きな音で音楽を聞くと、近所の（　）になる。', '迷惑', '無理', '失礼', '面倒', '「〜の迷惑になる」是給別人添麻煩。「失礼」不能用「近所の失礼になる」的形式。'],
  ['犬は鼻が（　）ので、遠くのにおいにも気づく。', '鋭い', '細かい', '濃い', '固い', '感官敏銳用「鋭い」，「鼻が鋭い」表示嗅覺靈敏。「細かい」是細小或仔細。'],
  ['隣の教室が（　）て、先生の声がよく聞こえない。', '騒がしく', '寂しく', '厳しく', '大人しく', '吵鬧到聽不清楚是「騒がしい」。「大人しい」是安靜乖巧，意思相反。'],
  ['自分だけ先に答えを見るなんて、（　）よ。', 'ずるい', '怪しい', '偉い', '鈍い', '只顧自己佔便宜、不公平是「ずるい」。「怪しい」是可疑，用來指看起來不對勁的人事物。'],

  // 副詞
  ['（　）作った料理なのに、誰も食べてくれなかった。', 'せっかく', 'わざと', 'なるべく', 'いよいよ', '「せっかく〜のに」表示特地花了工夫卻白費。「わざと」是故意，不接「〜のに」表達遺憾。'],
  ['遠いところを（　）来てくださって、ありがとうございます。', 'わざわざ', 'わざと', 'ついに', 'たまに', '感謝對方特地前來用「わざわざ」。「わざと」是故意做壞事或惡作劇，帶負面意味。'],
  ['駅で（　）高校時代の友人に会った。', 'たまたま', 'なるべく', 'ちっとも', '必ず', '偶然遇到用「たまたま」。「ちっとも」後面要接否定，「なるべく」是盡量，不用於偶然的事。'],
  ['赤ちゃんが寝ているので、ドアを（　）閉めた。', 'そっと', 'ぐっと', 'はっと', 'ずっと', '輕輕地、不出聲地動作是「そっと」。「ぐっと」是用力，與怕吵醒嬰兒相反。'],
  ['昨夜は疲れていたので、朝まで（　）眠った。', 'ぐっすり', 'すっかり', 'はっきり', 'さっぱり', '睡得很熟是「ぐっすり眠る」。「すっかり」是完全，通常接「忘れた」「変わった」等。'],
  ['弟は私を怒らせようとして、（　）間違えた答えを言った。', 'わざと', 'せっかく', 'たまたま', 'どうせ', '有意圖地故意做是「わざと」。「たまたま」是偶然，與「怒らせようとして」的目的矛盾。'],
  ['（　）間に合わないのだから、急いでも仕方がない。', 'どうせ', 'せっかく', 'まさか', 'たとえ', '「どうせ」表示反正結果都一樣，常接放棄的語氣。「たとえ」要接「〜ても」。'],
  ['健康のために、（　）階段を使うようにしている。', 'なるべく', 'ついに', 'まさか', 'めったに', '「なるべく」是盡可能。「めったに」後面要接否定。'],
  ['十年かかって、（　）夢がかなった。', 'ついに', 'いきなり', 'たまに', 'さっそく', '經過長時間後終於實現是「ついに」。「さっそく」是馬上，與「十年かかって」矛盾。'],
  ['新しいカメラを買ったので、（　）使ってみた。', 'さっそく', '今にも', 'めったに', 'すでに', '得到新東西後立刻使用是「さっそく」。「今にも」要接「〜そうだ」表示眼看就要發生。'],
  ['前を歩いていた人が（　）立ち止まったので、ぶつかりそうになった。', 'いきなり', 'やっと', '相変わらず', 'すでに', '毫無預兆地突然發生是「いきなり」。「やっと」是終於，表示期待已久。'],
  ['父は（　）怒らないが、その日は大きな声を出した。', 'めったに', 'たまに', 'よく', '必ず', '「めったに〜ない」表示很少。「たまに」是偶爾，不與否定搭配表達「很少」。'],
  ['久しぶりに会った先生は、（　）元気そうだった。', '相変わらず', 'さっそく', 'いきなり', 'ついでに', '和以前一樣沒變是「相変わらず」。「さっそく」是立刻著手，不能形容狀態。'],
  ['夜になって、雨は（　）強くなった。', 'ますます', 'めったに', 'せっかく', 'わざわざ', '程度越來越高是「ますます」。「めったに」後面要接否定，「わざわざ」是特地，不能形容雨勢變化。'],
  ['空が暗くなって、（　）雨が降りそうだ。', '今にも', 'とっくに', 'やっと', 'たった', '「今にも〜そうだ」表示眼看就要發生。「とっくに」是早就，用於已經發生的事。'],
  ['急いで行ったが、バスは（　）出てしまっていた。', 'とっくに', '今にも', 'まだ', 'いよいよ', '「とっくに」表示早就已經。「まだ」後面要接否定或持續狀態，與「出てしまっていた」矛盾。'],
  ['映画の最後の場面で、（　）泣いてしまった。', '思わず', 'わざと', 'なるべく', 'ぜひ', '不由自主地做出反應是「思わず」。「わざと」是故意，與「〜てしまった」的不自主語氣不合。'],
  ['駅まで行くなら、（　）この手紙を出してきてくれない？', 'ついでに', 'わざわざ', 'せっかく', 'いきなり', '做某事時順便做另一件事是「ついでに」。「わざわざ」是特地，與「既然要去車站」的順路語意相反。'],

  // 擬聲擬態語
  ['彼女は五年アメリカに住んでいたので、英語が（　）だ。', 'ぺらぺら', 'ぶらぶら', 'ばらばら', 'からから', '外語說得很流利是「ぺらぺら」。「ばらばら」是零散、四分五裂。'],
  ['初めて舞台に立つ前は、胸が（　）した。', 'どきどき', 'ぶらぶら', 'ごろごろ', 'ぴかぴか', '緊張或期待而心跳加速是「胸がどきどきする」。「ごろごろ」是無所事事地躺著或東西滾動。'],
  ['熱が高くて、立ち上がると（　）する。', 'ふらふら', 'ぶらぶら', 'ぐらぐら', 'ぺこぺこ', '身體虛弱站不穩是「ふらふら」。「ぐらぐら」用於桌椅、牙齒等物體搖晃。'],
  ['楽しみにしていた花火大会が中止になって、（　）した。', 'がっかり', 'すっきり', 'うっとり', 'のんびり', '期待落空而失望是「がっかり」。「すっきり」是舒暢清爽，與失望相反。'],
  ['電車が全然来ないので、（　）してきた。', 'いらいら', 'わくわく', 'にこにこ', 'ぴかぴか', '等得不耐煩、焦躁是「いらいら」。「わくわく」是期待雀躍。'],
  ['休みの日は、目的もなく町を（　）歩くのが好きだ。', 'ぶらぶら', 'ぺらぺら', 'ばらばら', 'ぴかぴか', '沒有目的地閒逛是「ぶらぶら歩く」。「ばらばら」是分散、零亂。'],
  ['床を一生懸命みがいたら、（　）になった。', 'ぴかぴか', 'ぺらぺら', 'ぶかぶか', 'ぼろぼろ', '擦得閃閃發亮是「ぴかぴか」。「ぼろぼろ」是破爛不堪，與擦亮結果相反。'],
  ['朝から何も食べていないので、おなかが（　）だ。', 'ぺこぺこ', 'からから', 'ぶかぶか', 'ぼろぼろ', '肚子很餓是「おなかがぺこぺこ」。「からから」用於口渴「のどがからから」。'],
  ['地震で棚が（　）揺れた。', 'ぐらぐら', 'ぶらぶら', 'ぺらぺら', 'ころころ', '物體大幅搖晃是「ぐらぐら揺れる」。「ころころ」是圓的東西滾動。'],
  ['祖母はいつも（　）笑っていて、優しい人だ。', 'にこにこ', 'いらいら', 'ぶつぶつ', 'ぐずぐず', '面帶微笑是「にこにこ笑う」。「ぶつぶつ」是小聲嘀咕抱怨。'],
  ['兄は文句を（　）言いながら、皿を洗っていた。', 'ぶつぶつ', 'ぴかぴか', 'ごろごろ', 'ふわふわ', '小聲碎念抱怨是「文句をぶつぶつ言う」。「ふわふわ」是輕飄飄、蓬鬆。'],
  ['日曜日は一日中家で（　）していた。', 'ごろごろ', 'ぴかぴか', 'ぺこぺこ', 'どきどき', '在家無所事事地躺著是「ごろごろする」。「どきどき」是心跳加速，不形容閒散。'],
]);
